INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Clearly trivial misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the auditor''s obligation regarding misstatements that are clearly trivial?', '["The auditor is not required to accumulate clearly trivial misstatements", "The auditor must report all clearly trivial misstatements to management", "The auditor must include clearly trivial misstatements in the summary of uncorrected misstatements", "The auditor must communicate clearly trivial misstatements to those charged with governance"]'::jsonb, 0, 'AU-C 450.05 states the auditor need not accumulate misstatements identified during the audit that are clearly trivial. "Clearly trivial" is not the same as "not material" — it sets a lower threshold below which items need not be tracked. Unlike immaterial misstatements that must still be accumulated, clearly trivial amounts are excluded from the summary entirely.', 'easy', 1),

-- Q2: medium / L2 — Iron curtain approach for evaluating misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Distributing, the auditor finds that a $40,000 overstatement of revenue has been carried forward from the prior year without correction. Under the iron curtain approach to evaluating misstatements, the auditor should:', '["Consider only the current-year effect of the misstatement on the financial statements", "Disregard the misstatement because it originated in a prior period", "Evaluate the total accumulated misstatement amount remaining in the current balance sheet", "Reverse the misstatement from the current-year income statement automatically"]'::jsonb, 2, 'AU-C 450.A16 describes the iron curtain approach, which quantifies a misstatement based on the effects of correcting the misstatement or reversing the balance sheet at the end of the current period. This focuses on the total accumulated amount. The rollover approach, by contrast, considers only the current-year originating effect, which would understate the cumulative impact on the balance sheet.', 'medium', 2),

-- Q3: medium / L3 — Qualitative factors in evaluating misstatement significance
(1, 'Misstatements and Control Deficiencies', 'While auditing Redstone Medical Group, the auditor identifies an uncorrected $18,000 misstatement in executive compensation disclosures. Overall materiality is $200,000. The audit partner asks the team to analyze whether qualitative factors elevate this misstatement''s significance. Which qualitative consideration most supports treating this misstatement as significant despite its small dollar amount?', '["The misstatement is below the clearly trivial threshold established for the engagement", "The misstatement relates to a sensitive area involving related party transactions and regulatory scrutiny", "The misstatement was discovered during substantive analytical procedures rather than tests of details", "The misstatement falls within the range of tolerable misstatement for the compensation account"]'::jsonb, 1, 'AU-C 450.11 requires auditors to consider qualitative factors when evaluating whether uncorrected misstatements are material. Misstatements affecting sensitive disclosures — such as executive compensation, related parties, or regulatory compliance — may be significant regardless of quantitative amount. A misstatement being below clearly trivial would mean it need not be accumulated at all, not that it has elevated significance.', 'medium', 3),

-- Q4: medium / L2 — Rollover approach to evaluating misstatements
(1, 'Misstatements and Control Deficiencies', 'Cascade Electronics has a $30,000 misstatement that originated two years ago and remains uncorrected. The auditor applies the rollover approach when evaluating the current-year impact. Under the rollover approach, the auditor evaluates the misstatement by focusing on:', '["The cumulative balance sheet effect as of the current period-end", "The amount of the misstatement that originated or was reversed in the current year", "The total misstatement from inception through the current period", "The net effect after considering both the income statement and balance sheet impacts simultaneously"]'::jsonb, 1, 'AU-C 450.A16 explains the rollover approach, which quantifies a misstatement based on the amount that originated in the current-year income statement. If no new misstatement originated or reversed in the current period, the rollover approach may show zero current-year effect. The iron curtain approach, by contrast, considers the total cumulative effect on the ending balance sheet regardless of when the error originated.', 'medium', 2),

-- Q5: medium / L2 — Management representation letter and uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Birchwood Properties, the auditor provides management with a summary listing three uncorrected misstatements totaling $45,000 against materiality of $300,000. Under AU-C 580, the management representation letter should include:', '["An acknowledgment that the effects of uncorrected misstatements are immaterial, individually and in the aggregate", "A guarantee that no additional misstatements exist beyond those identified", "A commitment to correct all misstatements in the subsequent period", "A statement that the uncorrected misstatements have been approved by the external auditors"]'::jsonb, 0, 'AU-C 580.14 requires the auditor to request that management include in the representation letter an acknowledgment that the effects of uncorrected misstatements aggregated during the audit are immaterial, individually and in the aggregate, to the financial statements as a whole. Management does not guarantee no other misstatements exist, nor is correction in subsequent periods required by this standard.', 'medium', 2),

-- Q6: hard / L4 — Evaluating pervasiveness of misstatement for opinion modification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeland Energy Corporation, the auditor identifies uncorrected misstatements totaling $2.1 million against materiality of $1.5 million. The misstatements are concentrated entirely within the inventory and cost of goods sold accounts. Management declines to make corrections. Under AU-C 705, the auditor must determine whether the misstatements are pervasive to the financial statements. Which conclusion best supports issuing a qualified rather than adverse opinion?', '["The misstatements, while material, are confined to specific accounts and do not represent a substantial proportion of the financial statements", "The auditor should negotiate with management to reduce the misstatement below materiality before issuing any modified opinion", "The misstatements exceed materiality, so the auditor must issue an adverse opinion regardless of pervasiveness", "The misstatements are automatically pervasive because they affect both the balance sheet and income statement"]'::jsonb, 0, 'AU-C 705.08 distinguishes qualified from adverse opinions based on whether material misstatements are also pervasive. Pervasive effects are those not confined to specific elements, accounts, or items, or those representing a substantial proportion of the financial statements. Misstatements concentrated in specific accounts without widespread balance sheet impact support a qualified opinion. The fact that misstatements exceed materiality alone does not mandate an adverse opinion — pervasiveness is a separate assessment.', 'hard', 4),

-- Q7: hard / L4 — Prior-year control deficiency not remediated
(1, 'Misstatements and Control Deficiencies', 'Granite Construction received a material weakness communication from its auditor last year regarding inadequate segregation of duties in cash disbursements. During the current-year audit, the auditor confirms the deficiency remains unremediated but no actual misstatements resulted. The auditor should evaluate this situation by:', '["Downgrading the material weakness to a significant deficiency because no misstatement occurred in the current year", "Issuing an adverse opinion due to the unremediated material weakness", "Noting the matter in the working papers only, since prior-year communications satisfy the reporting requirement", "Re-communicating the material weakness in writing because the condition continues to exist regardless of whether misstatements were detected"]'::jsonb, 3, 'AU-C 265.13 requires the auditor to communicate in writing material weaknesses identified during the current audit, including those previously communicated that have not been remediated. The absence of detected misstatements does not reduce the severity of the deficiency because the classification depends on reasonable possibility of material misstatement, not actual occurrence. Simply referencing prior communications is insufficient.', 'hard', 4),

-- Q8: medium / L2 — Distinction between design deficiency and operating effectiveness deficiency
(1, 'Misstatements and Control Deficiencies', 'During testing at Evergreen Logistics, the auditor notes that a purchase order approval control exists in the company''s policy manual but was not performed for 30 of 60 sampled transactions. Under AU-C 265, this situation represents:', '["A deficiency in the design of the control because the control should require dual approval", "A deficiency in the operating effectiveness of the control because the control exists but is not consistently applied", "A significant deficiency only if the deviations resulted in actual misstatements", "An immaterial finding that does not need to be evaluated for severity"]'::jsonb, 1, 'AU-C 265.07 distinguishes between design deficiencies (a control is missing or improperly designed) and operating effectiveness deficiencies (a properly designed control does not operate as designed). Since the purchase order approval control exists in policy but was not consistently performed, this is an operating effectiveness deficiency. A design deficiency would exist if no approval control were established at all.', 'medium', 2),

-- Q9: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, a control deficiency exists when:', '["A control is designed, implemented, or operated such that it is unable to prevent or detect misstatements on a timely basis", "A material misstatement has occurred and was not detected by the entity", "The auditor disagrees with management''s assessment of internal control effectiveness", "Internal audit has reported findings to the audit committee"]'::jsonb, 0, 'AU-C 265.07 defines a control deficiency as existing when the design or operation of a control does not allow management or employees to prevent, or detect and correct, misstatements on a timely basis. A deficiency does not require an actual misstatement to have occurred — it represents a weakness in the control system itself. Management disagreement and internal audit findings are separate matters.', 'easy', 1),

-- Q10: medium / L2 — Timing of control deficiency communication
(1, 'Misstatements and Control Deficiencies', 'The auditor of Westfield Manufacturing identifies three significant deficiencies during interim fieldwork in September. The fiscal year-end is December 31, and the audit report is expected in March. Under AU-C 265, when must the auditor communicate these significant deficiencies in writing to those charged with governance?', '["Within 30 days of identifying the deficiencies during interim fieldwork", "Before the audit report is issued, but no specific number of days is prescribed", "No later than 60 days following the report release date", "Only after the year-end audit is complete to ensure no additional deficiencies are found"]'::jsonb, 2, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses no later than 60 days following the report release date. The standard does not require communication within a fixed period from identification or before the audit report is issued, though timely communication is encouraged. Waiting until year-end completion is not required — the 60-day deadline runs from the report release date.', 'medium', 2),

-- Q11: easy / L1 — Summary of uncorrected misstatements (SUM)
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the summary of uncorrected misstatements prepared by the auditor?', '["To document all misstatements for legal proceedings against management", "To aggregate identified misstatements for evaluation of their effect on the financial statements", "To calculate the exact amount of adjustments required for a qualified opinion", "To replace the management representation letter regarding financial statement accuracy"]'::jsonb, 1, 'AU-C 450.06 requires the auditor to accumulate misstatements identified during the audit other than those that are clearly trivial. The summary of uncorrected misstatements (often called the SUM schedule) aggregates these items so the auditor can evaluate whether uncorrected misstatements, individually or in the aggregate, are material to the financial statements. It is an evaluation tool, not a legal document or replacement for representations.', 'easy', 1),

-- Q12: medium / L3 — Evaluating combined control deficiencies
(1, 'Misstatements and Control Deficiencies', 'While auditing Silverline Pharmaceuticals, the auditor identifies four control deficiencies in the revenue cycle: (1) credit memos lack supervisory approval, (2) shipping documents are not matched to invoices, (3) sales returns are recorded without verification, and (4) customer complaints are not tracked. Individually, none rises to a significant deficiency. The auditor should:', '["Report each deficiency separately to management and classify each as a non-significant control deficiency", "Disregard the deficiencies since none individually meets the threshold for reporting", "Defer the evaluation to the subsequent year to determine whether misstatements actually result from the deficiencies", "Evaluate whether the combination of deficiencies in the same business process constitutes a significant deficiency or material weakness"]'::jsonb, 3, 'AU-C 265.A13 states that a combination of control deficiencies affecting the same significant account or disclosure may collectively constitute a significant deficiency or material weakness even when individually none reaches that level. The auditor must evaluate interrelationships among deficiencies rather than assessing them in isolation. Deferring to subsequent years is inappropriate because the evaluation must occur in the period identified.', 'medium', 3),

-- Q13: medium / L3 — Misstatement in accounting estimates
(1, 'Misstatements and Control Deficiencies', 'The auditor of Clearwater Insurance is evaluating the allowance for policyholder claims. Management''s estimate is $4.2 million, while the auditor''s independent estimate yields a range of $4.8 million to $5.3 million. Under AU-C 540, how should the auditor treat the difference between management''s point estimate and the auditor''s range?', '["The entire difference of $600,000 to $1.1 million must be recorded as a factual misstatement", "The auditor should average the range endpoints and record the midpoint difference as the misstatement", "The minimum difference of $600,000 should be included as a likely misstatement in the summary of uncorrected misstatements", "The auditor cannot identify a misstatement because the estimate falls within an acceptable range of outcomes"]'::jsonb, 2, 'AU-C 540.18 indicates that when the auditor''s estimate establishes a range, amounts outside that range are considered misstatements. Since management''s $4.2 million falls below the auditor''s range of $4.8–$5.3 million, the minimum difference ($600,000) represents a likely misstatement. The full difference is not necessarily factual because estimates involve judgment, and averaging endpoints is not prescribed by the standard.', 'medium', 3),

-- Q14: easy / L1 — Misstatement arising from fraud vs error
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 240, what distinguishes a misstatement arising from fraud from a misstatement arising from error?', '["The dollar amount of the misstatement", "Whether the underlying action was intentional or unintentional", "Whether the misstatement affects the balance sheet or income statement", "The materiality threshold applied to the misstatement"]'::jsonb, 1, 'AU-C 240.02 distinguishes fraud from error based on intent. Fraud involves intentional acts by one or more individuals, including management, those charged with governance, employees, or third parties, that result in misstatement of the financial statements. Errors are unintentional misstatements. The distinction does not depend on dollar amount, which accounts are affected, or the materiality threshold.', 'easy', 1),

-- Q15: medium / L2 — Communication to management vs those charged with governance
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Ridge Healthcare, the auditor identifies several control deficiencies that do not rise to the level of significant deficiencies or material weaknesses. Under AU-C 265, how should the auditor communicate these less severe deficiencies?', '["The auditor is required to communicate all control deficiencies in writing to those charged with governance", "The auditor has no obligation to communicate deficiencies that are less severe than significant deficiencies", "An appendix to the management representation letter is required for all lesser deficiencies", "The auditor should communicate these deficiencies to management and determine whether to communicate them to those charged with governance"]'::jsonb, 3, 'AU-C 265.12 requires the auditor to communicate to management control deficiencies identified during the audit that are of sufficient importance to merit management''s attention, even when those deficiencies do not rise to significant deficiency or material weakness level. The auditor then determines whether to also communicate these to those charged with governance. Written communication to governance is specifically required only for significant deficiencies and material weaknesses.', 'medium', 2),

-- Q16: hard / L4 — Evaluating whether misstatement pattern indicates fraud
(1, 'Misstatements and Control Deficiencies', 'During the audit of Apex Trading Corporation, the auditor discovers that over three consecutive quarters, revenue was overstated by small amounts ($12,000, $15,000, and $18,000) that individually and in aggregate fall below materiality of $250,000. Each overstatement brought reported earnings exactly to analyst consensus estimates. Under AU-C 240, the auditor should conclude that:', '["The misstatements are immaterial and do not require further investigation since they are below both individual and aggregate materiality", "The pattern of misstatements meeting analyst expectations is a fraud risk indicator requiring expanded procedures and possible reconsideration of the overall audit strategy", "The misstatements should be treated as routine accounting errors since the dollar amounts are small", "The auditor should reduce the materiality threshold to capture these misstatements in future periods"]'::jsonb, 1, 'AU-C 240.35 requires the auditor to evaluate whether identified misstatements may be indicative of fraud. A pattern of immaterial misstatements that consistently achieve a specific earnings target is a strong indicator of intentional manipulation, regardless of dollar amount. AU-C 450.11 also notes that qualitative factors, including whether a misstatement could be indicative of fraud, affect the evaluation. Simply noting the amounts are below materiality ignores the fraud risk dimension.', 'hard', 4),

-- Q17: easy / L1 — Types of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Which three categories of misstatements does AU-C 450 identify for auditor evaluation?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Material misstatements, immaterial misstatements, and trivial misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements", "Intentional misstatements, unintentional misstatements, and systematic misstatements"]'::jsonb, 0, 'AU-C 450.A3 identifies three types: factual misstatements (about which there is no doubt), judgmental misstatements (arising from management''s judgments about estimates or accounting policies the auditor considers unreasonable), and projected misstatements (the auditor''s best estimate of misstatements in populations based on audit sample results). The other answer sets mix classification criteria that are not the framework established by AU-C 450.', 'easy', 1),

-- Q18: medium / L2 — Indicators that suggest a material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northstar Retail, the auditor discovers that the company''s quarterly financial statements filed with the SEC contained a material misstatement that was subsequently corrected through a restatement. Under AU-C 265, this restatement is best characterized as:', '["A routine correction that has no bearing on the evaluation of control deficiencies", "Evidence of a significant deficiency that may or may not rise to the level of material weakness", "An error in judgment that does not constitute a control deficiency", "A strong indicator of a material weakness in internal control over financial reporting"]'::jsonb, 3, 'AU-C 265.A10 identifies specific indicators of material weakness, including restatement of previously issued financial statements to reflect the correction of a material misstatement due to error or fraud. A restatement demonstrates that existing controls failed to prevent or detect a material misstatement before the financial statements were issued, meeting the definition of material weakness. It is not merely a routine correction or lesser deficiency.', 'medium', 2),

-- Q19: medium / L3 — Effect of compensating controls on severity evaluation
(1, 'Misstatements and Control Deficiencies', 'The auditor of Valley Stream Manufacturing identifies that the company lacks automated three-way matching between purchase orders, receiving reports, and invoices. However, the controller personally reviews all payments over $5,000 before they are released, and this review has been consistently performed. The auditor should evaluate the severity of the three-way matching deficiency by:', '["Ignoring the controller''s review because compensating controls cannot reduce the severity of a primary control deficiency", "Automatically classifying the deficiency as a significant deficiency because automated controls are required for the purchasing cycle", "Considering the controller''s review as a compensating control that may reduce the severity of the deficiency, provided the compensating control has been tested and found effective", "Treating the controller''s review as the primary control and eliminating the three-way matching deficiency entirely"]'::jsonb, 2, 'AU-C 265.A8 indicates that compensating controls should be considered when evaluating the severity of a control deficiency. If a compensating control effectively reduces the likelihood that a material misstatement would not be prevented or detected, it may reduce the severity of the primary deficiency. However, the compensating control must be tested for operating effectiveness. It does not eliminate the underlying deficiency nor should it be ignored entirely.', 'medium', 3),

-- Q20: medium / L3 — Evaluating misstatements near materiality threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeway Consulting, the auditor accumulates uncorrected misstatements totaling $185,000 against overall materiality of $200,000. Management refuses to make any adjustments. The auditor considers several courses of action. Which response is most appropriate?', '["Issue an unmodified opinion because the aggregate misstatement is below materiality", "Automatically issue a qualified opinion because the misstatement exceeds 90% of materiality", "Increase the materiality level to $250,000 to accommodate the uncorrected misstatements", "Request management to correct at least some misstatements to bring the aggregate further below materiality, and consider the effect on the opinion if management refuses"]'::jsonb, 3, 'AU-C 450.12 states that if management refuses to correct some or all misstatements, the auditor should understand the reasons and consider them when evaluating the financial statements as a whole. When uncorrected misstatements approach materiality, the auditor should consider whether additional misstatements may exist and request corrections. Issuing an unmodified opinion is risky at this proximity, but there is no automatic threshold for qualification. Increasing materiality to accommodate misstatements is inappropriate.', 'medium', 3),

-- Q21: easy / L1 — Who can identify control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, control deficiencies may be identified by which parties?', '["Only the external auditor during the annual financial statement audit", "Only internal auditors who specialize in evaluating controls", "The external auditor, internal auditors, or management through their own monitoring activities", "Only management through its annual assessment of internal controls"]'::jsonb, 2, 'AU-C 265.A1 acknowledges that control deficiencies can be identified by the auditor, internal auditors, or through management''s own monitoring activities. The external auditor is required to evaluate deficiencies identified during the audit, but deficiencies can come to the auditor''s attention from multiple sources. Limiting identification to any single party is incorrect.', 'easy', 1),

-- Q22: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'In the context of audit sampling, what is the purpose of tolerable misstatement?', '["To set the maximum misstatement in a population that the auditor is willing to accept", "To establish the dollar amount above which all misstatements must be corrected", "To define the threshold below which misstatements are considered clearly trivial", "To calculate the projected misstatement for the entire population"]'::jsonb, 0, 'AU-C 530.A3 defines tolerable misstatement as a monetary amount set by the auditor to reduce to an appropriately low level the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality. It represents the maximum error the auditor can accept in a population and still conclude the account is not materially misstated. It is distinct from the clearly trivial threshold and from projected misstatement calculations.', 'easy', 1),

-- Q23: hard / L4 — IT general control deficiency cascading to application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Financial Services, the auditor discovers that the company''s database administrator has unrestricted access to modify production data without logging or secondary review. No misstatements have been detected, and all application-level controls over financial reporting tested effectively. The auditor should evaluate this IT general control deficiency by recognizing that:', '["The deficiency is mitigated because application-level controls tested effectively, reducing the severity to a non-reportable control deficiency", "The deficiency only affects IT operations and is outside the scope of the financial statement audit", "The unrestricted access undermines the reliability of application controls that depend on data integrity, potentially elevating the deficiency to material weakness regardless of application control test results", "The absence of detected misstatements confirms the control environment is functioning adequately despite the access issue"]'::jsonb, 2, 'AU-C 265.A7 recognizes that IT general controls support the continued proper operation of application controls. When a database administrator can modify production data without logging, the integrity of all data processed by application controls is undermined. Effective application control testing may be unreliable because the underlying data could have been altered. The absence of detected misstatements does not mitigate the reasonable possibility that the deficiency could result in a material misstatement.', 'hard', 4),

-- Q24: easy / L2 — Documenting misstatements in working papers
(1, 'Misstatements and Control Deficiencies', 'While testing inventory at Brookfield Supply Company, the auditor finds that five of forty items sampled have incorrect unit costs, resulting in a known misstatement of $3,200 and a projected misstatement of $16,000 for the entire population. Under AU-C 450, the auditor should document:', '["Only the $16,000 projected misstatement since it represents the population estimate", "Only the $3,200 known misstatement since projected amounts are estimates", "Neither amount because both are below the materiality threshold", "Both the $3,200 known misstatement and the $16,000 projected misstatement in the summary of uncorrected misstatements"]'::jsonb, 3, 'AU-C 450.06 requires the auditor to accumulate all misstatements identified during the audit, other than those that are clearly trivial. This includes both the known misstatement from items actually tested ($3,200) and the projected misstatement for the untested portion of the population ($16,000). Both amounts inform the evaluation of aggregate uncorrected misstatements against materiality. Documenting only one component provides an incomplete picture.', 'easy', 2),

-- Q25: hard / L3 — Evaluating fraud-related control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Aerospace, the auditor discovers that the CFO overrode the automated journal entry approval process to record $85,000 in top-side adjustments, none of which were reviewed by anyone else. The adjustments were determined to be legitimate business entries after investigation. Overall materiality is $500,000. When evaluating the severity of this control deficiency, the auditor should give the greatest weight to:', '["The dollar amount of the adjustments relative to materiality, which suggests the deficiency is not significant", "The legitimacy of the adjustments, which confirms the control environment is functioning despite the override", "The nature of the override, because management override of controls is an inherent fraud risk factor that may constitute a material weakness regardless of dollar amount", "The number of override instances, which determines whether the deficiency is isolated or systemic"]'::jsonb, 2, 'AU-C 265.A12 and AU-C 240.31 emphasize that management override of controls represents a unique fraud risk. Even when the resulting entries are legitimate, the ability of management to circumvent controls without detection represents a failure in the control environment. The nature of the deficiency — involving override of a preventive control by senior management — weighs heavily in the severity evaluation, potentially supporting material weakness classification regardless of the dollar amount or legitimacy of specific entries.', 'hard', 3),

-- Q26: easy / L1 — Written communication format for control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, significant deficiencies and material weaknesses must be communicated to those charged with governance in what format?', '["Oral communication only, documented in the audit working papers", "Either oral or written communication at the auditor''s discretion", "Through inclusion in the auditor''s report on the financial statements", "Written communication"]'::jsonb, 3, 'AU-C 265.11 requires that the auditor communicate in writing to those charged with governance significant deficiencies and material weaknesses identified during the audit. Oral communication alone is insufficient for these severity levels, though the auditor may also communicate them orally. These communications are separate from the auditor''s report on the financial statements, which addresses the opinion on the financial statements rather than internal control matters.', 'easy', 1),

-- Q27: medium / L2 — Effect of misstatement correction on further audit procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sandstone Properties, the auditor identifies a $120,000 misstatement in depreciation expense. Management promptly corrects the entry. The auditor should next consider whether:', '["The corrected misstatement indicates a control deficiency or pattern that may require additional audit procedures", "The corrected misstatement can be removed from the audit working papers entirely", "No further action is needed since the financial statements are now correct", "The correction requires the auditor to expand testing of all other expense accounts"]'::jsonb, 0, 'AU-C 450.08 states that the auditor shall consider whether identified misstatements may indicate additional misstatements that, when combined with other uncorrected misstatements, could be material. Even after correction, the auditor should evaluate whether the misstatement signals a control deficiency per AU-C 265 or suggests a pattern requiring expanded procedures. Simply removing the item from working papers or taking no further action ignores the diagnostic value of the misstatement.', 'medium', 2),

-- Q28: hard / L4 — Interaction between materiality revision and misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Midway through the audit of Crestline Energy, the auditor revises overall materiality downward from $400,000 to $250,000 based on updated financial results. Previously accumulated uncorrected misstatements total $210,000. The auditor must now evaluate the implications of this materiality revision on the audit. Which response reflects the most appropriate course of action?', '["The previously accumulated misstatements remain below the revised materiality, so no changes to the audit plan are needed", "The auditor should reassess whether previously evaluated misstatements and control deficiencies require reclassification and determine if additional procedures are needed to detect misstatements at the lower threshold", "The auditor should discard the previous materiality and start the misstatement evaluation from the beginning of the audit", "The auditor should communicate the materiality change to management and allow them to decide which misstatements to correct"]'::jsonb, 1, 'AU-C 320.13 requires the auditor to revise materiality if information comes to attention that would have caused a different amount. When materiality decreases, previously immaterial misstatements may become material, and previously tolerable control deficiencies may need reclassification to higher severity. The auditor must also consider whether lower materiality requires additional procedures. While $210,000 is technically below $250,000, the proximity demands careful reassessment. Discarding prior work or delegating decisions to management are both inappropriate.', 'hard', 4),

-- Q29: medium / L3 — Evaluating misstatement in disclosure vs recognition
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Marine Industries, the auditor discovers that the company failed to disclose a $2 million contingent liability related to ongoing litigation that management classified as reasonably possible. No amounts were recognized in the financial statements. Under AU-C 450, the auditor should treat this omission as:', '["Not a misstatement because reasonably possible contingencies do not require financial statement recognition", "An immaterial omission because the amount was not recorded in the financial statements", "A misstatement in disclosures that must be evaluated for materiality just as misstatements in recognition would be", "A scope limitation that prevents the auditor from issuing an unmodified opinion"]'::jsonb, 2, 'AU-C 450.04 defines misstatements broadly to include misstatements of amounts, classification, presentation, or disclosure. A failure to disclose a reasonably possible contingency required by ASC 450-20-50 constitutes a disclosure misstatement. While the contingency is correctly not recognized (only probable amounts require accrual), the disclosure omission is independently evaluated against materiality. It is not a scope limitation because the auditor has identified the omission.', 'medium', 3),

-- Q30: medium / L3 — Distinguishing between inconsequential and significant deficiencies in practice
(1, 'Misstatements and Control Deficiencies', 'While auditing Timberline Logistics, the auditor notes that month-end bank reconciliations are consistently prepared two weeks late but are eventually completed accurately. No misstatements have resulted from the delays. The auditor evaluates the severity of this timing deficiency. Which analysis best supports classifying this as a significant deficiency rather than an inconsequential control deficiency?', '["The two-week delay creates a window during which errors or fraud in cash accounts could go undetected, increasing the reasonable possibility that a material misstatement could occur before being identified", "The delay is inconsequential because no misstatements resulted from the late reconciliations", "Late reconciliations are always material weaknesses because cash is a high-risk account", "The deficiency should not be reported because the reconciliations are eventually completed accurately"]'::jsonb, 0, 'AU-C 265.A8 requires evaluating both the likelihood and magnitude components of a control deficiency. A two-week delay in bank reconciliations creates a detection gap during which misstatements — including those arising from fraud — could accumulate undetected in a high-volume, high-risk account. The absence of historical misstatements does not eliminate the reasonable possibility of future occurrence. The fact that reconciliations are eventually accurate addresses the design but not the timeliness of detection.', 'medium', 3)
;

COMMIT;
